function notionText(runs) {
  if (!Array.isArray(runs)) return "";
  return runs.map((part) => part?.plain_text ?? part?.text?.content ?? "").join("");
}

function notionPage(page) {
  const pageId = page?.pageId ?? page?.id;
  const createdTime = page?.createdTime ?? page?.created_time;
  if (
    typeof pageId !== "string" ||
    !/^[\da-f]{8}(?:-[\da-f]{4}){3}-[\da-f]{12}$/i.test(pageId) ||
    typeof createdTime !== "string" ||
    !Number.isFinite(Date.parse(createdTime))
  ) {
    throw new Error("Notion returned a page without a valid ID and creation time");
  }
  const properties = Object.values(page.properties ?? {});
  const title =
    properties.find((property) => property?.type === "title")?.title ??
    page.properties?.Name?.title;
  return {
    pageId: pageId.toLowerCase(),
    createdTime,
    pageTitle: notionText(title).trim() || "Untitled",
  };
}

function ignoreNotionChildren(type) {
  return ["image", "video", "child_page", "child_database", "link_to_page"].includes(type);
}

function notionBlockText(block) {
  if (["image", "video", "link_to_page"].includes(block.type)) return "";
  if (typeof block.content === "string") return block.content;
  const details = block[block.type] ?? {};
  if (block.type === "table_row") return (details.cells ?? []).map(notionText).join("\t").trim();
  if (block.type === "equation") return details.expression ?? "";
  if (block.type === "child_page" || block.type === "child_database") return details.title ?? "";
  return notionText(details.rich_text ?? details.text);
}

async function readNotionDocument(page, listChildren) {
  const source = notionPage(page);
  const content = [];
  const seen = new Set([source.pageId]);
  async function visit(blockId) {
    let cursor;
    const cursors = new Set();
    do {
      const result = await listChildren({
        blockId,
        pageSize: 100,
        ...(cursor ? { startCursor: cursor } : {}),
      });
      if (!Array.isArray(result?.results) || typeof result.has_more !== "boolean") {
        throw new Error("Notion returned an incomplete block list");
      }
      for (const block of result.results) {
        const id = block?.id;
        if (
          typeof id !== "string" ||
          !/^[\da-f]{8}(?:-[\da-f]{4}){3}-[\da-f]{12}$/i.test(id) ||
          typeof block.type !== "string" ||
          seen.has(id.toLowerCase())
        ) {
          throw new Error("Notion returned a missing or repeated block ID");
        }
        seen.add(id.toLowerCase());
        const text = notionBlockText(block);
        if (text.trim()) content.push(text);
        if (block.has_children && !ignoreNotionChildren(block.type)) await visit(id);
      }
      cursor = result.has_more ? result.next_cursor : null;
      if (result.has_more && (typeof cursor !== "string" || !cursor || cursors.has(cursor))) {
        throw new Error("Notion did not advance the block list cursor");
      }
      cursors.add(cursor);
    } while (cursor);
  }
  await visit(source.pageId);
  return { ...source, text: content.join("\n") };
}

export default async ({ events }, context) => {
  const documents = [];
  const seen = new Set();
  for (const page of events) {
    if (page.event !== "page_added" || seen.has(page.pageId)) continue;
    seen.add(page.pageId);
    const doc = await readNotionDocument(page, (input) =>
      context.actions.call("notion.list_block_children", input),
    );
    if (doc.text.trim()) documents.push(doc);
  }
  return { documents, hasText: documents.length > 0 };
};

