function pineconeIndex(index) {
  const match = /^(?:https:\/\/)?([a-z0-9-]+(?:\.[a-z0-9-]+)*\.pinecone\.io)\/?$/i.exec(
    index?.host ?? "",
  );
  if (
    index?.dimension !== 768 ||
    index.metric !== "cosine" ||
    (index.vector_type != null && index.vector_type !== "dense") ||
    !match ||
    index.status?.ready !== true
  ) {
    throw new Error("Configure a ready 768-dimensional dense cosine Pinecone index");
  }
  return "https://" + match[1];
}

function pineconeNamespace(namespace) {
  if (typeof namespace !== "string" || !/^[A-Za-z0-9_-]{1,128}$/.test(namespace)) {
    throw new Error("Enter a Pinecone namespace for these Gemini embeddings");
  }
  return namespace;
}

export default async ({ index, vectors, namespace }, context) => {
  const target = pineconeIndex(index);
  const chosenNamespace = pineconeNamespace(namespace);
  if (!vectors.length) return { upserted: 0 };
  const result = await context.actions.call("pinecone.upsert_vectors", {
    indexHost: target,
    vectors,
    namespace: chosenNamespace,
  });
  if (result.upsertedCount !== vectors.length)
    throw new Error("Pinecone did not confirm every vector");
  return { upserted: result.upsertedCount };
};
